#!/usr/bin/env python3
"""Summarize the differences between two OpenAPI schemas generated by "make genschema".

Usage: api_schema_diff.py REFERENCE_SCHEMA NEW_SCHEMA

Prints a Markdown summary of the operations (path and method) and component
schemas that were added, removed or changed, and exits with 1 when the
schemas differ, 0 when they are the same. CI uses it in
.github/workflows/api_schema_check.yml.
"""

import json
import sys

HTTP_METHODS = ('get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace')


def operations(schema):
    ops = {}
    for path, item in schema.get('paths', {}).items():
        for method, operation in item.items():
            if method in HTTP_METHODS:
                ops[f'{method.upper()} {path}'] = operation
    return ops


def components(schema):
    return {f'{kind}/{name}': value for kind, entries in schema.get('components', {}).items() for name, value in entries.items()}


def compare(old, new):
    added = sorted(set(new) - set(old))
    removed = sorted(set(old) - set(new))
    changed = sorted(key for key in set(old) & set(new) if old[key] != new[key])
    return added, removed, changed


def section(title, added, removed, changed, limit=200):
    lines = []
    for label, keys in (('Added', added), ('Removed', removed), ('Changed', changed)):
        if not keys:
            continue
        lines.append(f'**{title} {label.lower()} ({len(keys)})**')
        lines.append('')
        lines.extend(f'- `{key}`' for key in keys[:limit])
        if len(keys) > limit:
            lines.append(f'- ... and {len(keys) - limit} more')
        lines.append('')
    return lines


def main():
    if len(sys.argv) != 3:
        sys.exit(__doc__)
    with open(sys.argv[1]) as f:
        old = json.load(f)
    with open(sys.argv[2]) as f:
        new = json.load(f)

    if old == new:
        print('No API schema changes.')
        return 0

    lines = section('Operations', *compare(operations(old), operations(new)))
    lines += section('Components', *compare(components(old), components(new)))
    rest_old = {k: v for k, v in old.items() if k not in ('paths', 'components')}
    rest_new = {k: v for k, v in new.items() if k not in ('paths', 'components')}
    changed_top = sorted(k for k in set(rest_old) | set(rest_new) if rest_old.get(k) != rest_new.get(k))
    if changed_top:
        lines.append('**Other top-level keys changed:** ' + ', '.join(f'`{k}`' for k in changed_top))
        lines.append('')
    print('\n'.join(lines).rstrip())
    return 1


if __name__ == '__main__':
    sys.exit(main())
